&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Use of Fingers/Hands:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Typing, or otherwise working primarily with fingers rather than with whole hand or arm as in handling.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Talking:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Expressing or exchanging ideas by means of the spoken word. Those activities in which they must convey detail or important spoken instructions to other workers accurately, loudly, or quickly.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Hearing:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Ability to receive detailed information through oral communication, and to make fine discriminations in sound, such as when making fine adjustments on machine parts.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Repetitive motions&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;: Substantial movements (motions) of the wrists, hands, and/or fingers.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Vision:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; The incumbent is required to distinguish between true colors, perceive depth, and partial field of vision is required at a minimum for the position.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:256,&amp;quot;469777462&amp;quot;:[360,8630],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,4]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Work Environment&lt;/span&gt;&lt;/strong&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The worker is subject to inside environmental conditions&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;: Protection from weather conditions but not necessarily from temperature changes.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The worker is subject to outside environmental conditions:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; NO effective protection from weather.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The worker is subject to both environmental conditions:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Activities occur inside and outside.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The worker is subject to noise:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; There is sufficient noise to cause the worker to shout in order to be heard above the ambient noise level.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;Calibri&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559684&amp;quot;:-2,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The worker is subject to hazards:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Includes a variety of physical conditions, such as proximity to moving mechanical parts, electrical current, working on scaffolding and high places, exposure to high heat or exposure to chemicals.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:256,&amp;quot;469777462&amp;quot;:[360,8630],&amp;quot;469777927&amp;quot;:[0,0],&amp;quot;469777928&amp;quot;:[1,4]}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About Tanium&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;Tanium is the Autonomous IT company. Driven by AI and real-time endpoint intelligence, Tanium Autonomous IT empowers IT and security teams to make their organizations unstoppable.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Many of the world’s leading organizations trust Tanium’s single, unified platform for endpoint management and security to innovate faster, stay resilient and move business forward with confidence, at scale. To learn how Tanium delivers Autonomous IT for unstoppable business – visit &lt;u&gt;&lt;a id=&quot;OWA8cd82040-d6a4-2e07-8c22-f773746075e4&quot; href=&quot;http://www.tanium.com/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;0&quot;&gt;www.tanium.com&lt;/a&gt;&lt;/u&gt; and&amp;nbsp;follow us on &lt;u&gt;&lt;a id=&quot;OWA51246dd5-7f28-280e-6637-139dda4774bb&quot; href=&quot;https://www.linkedin.com/company/tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt; and &lt;u&gt;&lt;a id=&quot;OWAd79eefc3-ede9-5e26-14d4-517b82af2392&quot; href=&quot;https://twitter.com/Tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;2&quot;&gt;X&lt;/a&gt;&lt;/u&gt;.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;On a mission. Together.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Tanium, we are stewards of a culture that emphasizes the importance of collaboration, respect, and diversity. In our pursuit of revolutionizing the way some of the largest enterprises and governments in the world solve their most difficult IT challenges, we are strengthened by our unique perspectives and by our collective actions.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;As a global organization with stakeholders around the world, it’s imperative that the diversity of our customers and communities is reflected internally in our team members. We strive to create a diverse and inclusive environment where everyone feels they have opportunities to succeed and grow because we know that only together can we do great things. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our commitment to excellence and innovation has earned us a place on the Forbes Cloud 100 list for ten consecutive years, and we continue to be recognized worldwide as a great place to work.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&lt;strong&gt;Taking care of our team members&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Each of our team members has 5 days set aside as volunteer time off (VTO) to contribute to the communities they live in and give back to the causes they care about most.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Tanium is an Equal Opportunity and Affirmative Action employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, age, gender identity, sexual orientation, disability, protected Veteran status, or other legally protected categories. If you require a reasonable accommodation in searching for a job opening, completing an application, interviewing, or completing any pre-employment testing or requirements, please contact&amp;nbsp;&lt;a href=&quot;mailto:accommodations@tanium.com&quot;&gt;accommodations@tanium.com&lt;/a&gt;. For more information refer to the “Know Your Rights” poster which is available here -&amp;nbsp;&lt;a href=&quot;https://www.eeoc.gov/poster&quot; target=&quot;_blank&quot;&gt;https://www.eeoc.gov/poster&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;Please be aware of job offers coming from people claiming to be Tanium employees. Tanium employees will only use @tanium.com email addresses to communicate with you, will have video interviews with you, and will never ask you for money.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.cigna.com/legal/compliance/machine-readable-files&quot; target=&quot;_blank&quot;&gt;This link&lt;/a&gt; leads to the machine readable files that are made available in response to the federal Transparency in Coverage Rule and includes negotiated service rates and out-of-network allowed amounts between health plans and healthcare providers. The machine-readable files are formatted to allow researchers, regulators, and application developers to more easily access and analyze data.&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;For more information on how Tanium processes your personal data, please see our&amp;nbsp;&lt;a href=&quot;https://www.tanium.com/privacy-policy/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-safelink=&quot;true&quot; data-linkindex=&quot;0&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

a16z-thatch:greenhouse:4944171008.descriptionHtml:
&lt;h3&gt;About the role&lt;/h3&gt;
&lt;p&gt;Thatch is rewiring how health benefits work. We build software that gives employees real control over how they use their benefits.&lt;/p&gt;
&lt;p&gt;We&#39;re looking for an Analytics Engineer to own the data models, metrics, and dashboards the company runs on. You&#39;ll define how we measure the business, from source data through the numbers that leadership, growth, finance, and operations use every day. This work touches real money and real healthcare decisions. Consistency and reliability matter, but so does making the data simple to use for the teams who depend on it.&lt;/p&gt;
&lt;h3&gt;What you will do&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Take ownership of meaningful metrics and data products, from definition through adoption.&lt;/li&gt;
&lt;li&gt;Build and maintain dbt models that define how we measure the business.&lt;/li&gt;
&lt;li&gt;Design and maintain dashboards used by growth, finance, and operations to make day-to-day decisions.&lt;/li&gt;
&lt;li&gt;Improve data quality through testing, monitoring, and validation.&lt;/li&gt;
&lt;li&gt;Enable self-serve analytics so teams can answer their own questions and move faster.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What we are looking for&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience building analytics models and dashboards in a production environment.&lt;/li&gt;
&lt;li&gt;Strong SQL skills and experience with dbt or similar tools, and working knowledge of python for ad-hoc analysis.&lt;/li&gt;
&lt;li&gt;Strong intuition for metric design, including grain, aggregation, and edge cases.&lt;/li&gt;
&lt;li&gt;Eagerness to work closely with stakeholders to define problems and translate them into metrics, models, and analytic tools.&lt;/li&gt;
&lt;li&gt;Good judgment when balancing speed, accuracy, and maintainability.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;We hire across levels and care most about the scope you’ve owned, the impact you’ve had, and how you make decisions.&lt;/p&gt;
&lt;h3&gt;Tools and tech stack&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;dbt and SQL for modeling.&lt;/li&gt;
&lt;li&gt;Snowflake as our data warehouse (migrating from Redshift).&lt;/li&gt;
&lt;li&gt;Omni for BI, with tools like Hex for ad hoc analysis.&lt;/li&gt;
&lt;li&gt;GitHub with CI/CD for version control.&lt;/li&gt;
&lt;li&gt;AI tools (e.g., Claude, ChatGPT, Copilot) are woven into our daily development and analysis workflow.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You won’t work directly in our application layer day-to-day, but understanding source data from systems like Ruby on Rails is important.&lt;/p&gt;
&lt;h3&gt;Experience that stands out&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience with data testing, CI/CD, and building reliable, observable data systems.&lt;/li&gt;
&lt;li&gt;Partnering closely with finance, growth, or go-to-market teams.&lt;/li&gt;
&lt;li&gt;Building self-serve analytics tools that reduce ad hoc requests.&lt;/li&gt;
&lt;li&gt;Working in healthcare, fintech, or other complex, regulated domains.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;How we work&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;We move quickly and are biased toward action.&lt;/li&gt;
&lt;li&gt;We ship early, learn from real usage, and iterate.&lt;/li&gt;
&lt;li&gt;We operate with trust, ownership, and high empathy.&lt;/li&gt;
&lt;li&gt;We value clarity over ceremony and quality over shortcuts.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What to expect&lt;/h3&gt;
&lt;p&gt;We aim to move quickly, and most candidates complete the process within 2–3 weeks. You can expect:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;An initial conversation with a recruiter.&lt;/li&gt;
&lt;li&gt;A conversation with the hiring manager.&lt;/li&gt;
&lt;li&gt;A take-home analytics exercise.&lt;/li&gt;
&lt;li&gt;A review of your work, including modeling and coding exercises with the team, and a discussion with cross-functional partners.&lt;/li&gt;
&lt;li&gt;A final conversation with engineering and company leadership.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Estimated Compensation Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$160,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$190,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;section class=&quot;text-base text-gray-500&quot;&gt;
&lt;div class=&quot;mt-10 text-base text-gray-500&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/section&gt;
&lt;div class=&quot;mt-10&quot;&gt;
&lt;h3 class=&quot;mb-4 text-xl font-extrabold text-gray-900 sm:text-3xl md:text-2xl&quot;&gt;About Thatch&lt;/h3&gt;
&lt;p class=&quot;mb-4 text-base text-gray-500&quot;&gt;We’re a fully distributed early stage company using technology to change the way America does healthcare. We’re a happy, friendly, high-velocity team. You can read&amp;nbsp;&lt;a class=&quot;font-medium text-indigo-600 hover:text-indigo-500&quot; href=&quot;https://thatch.ai/company&quot;&gt;more on Thatch here&lt;/a&gt;.&lt;/p&gt;
&lt;/div&gt;&lt;/div&gt;

a16z-waymo:greenhouse:7902119.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Waymo is an autonomous driving technology company with the mission to be the world&#39;s most trusted driver. Since its start as the Google Self-Driving Car Project in 2009, Waymo has focused on building the Waymo Driver—The World&#39;s Most Experienced Driver™—to improve access to mobility while saving thousands of lives now lost to traffic crashes. The Waymo Driver powers Waymo’s fully autonomous ride-hail service and can also be applied to a range of vehicle platforms and product use cases. The Waymo Driver has provided over ten million rider-only trips, enabled by its experience autonomously driving over 100 million miles on public roads and tens of billions in simulation across 15+ U.S. states.&lt;/p&gt;&lt;/div&gt;&lt;p data-path-to-node=&quot;11&quot;&gt;We are looking for a passionate Full Stack Software Engineer to join the Waymo UX Depot team. Our work involves building both the client-facing interfaces and backend infrastructure that power the mobile and web applications used by Waymo and enterprise partners to manage fleets of autonomous vehicles. You will help us enhance mobile apps for operational personnel, scale real-time tools for fleet data collection, and build intuitive web views to visualize and control complex depot deployment processes.&lt;/p&gt;
&lt;p data-path-to-node=&quot;12&quot;&gt;You will be developing high-quality, reliable, and scalable end-to-end systems that form the backbone of mission-critical Waymo infrastructure, enabling new functionalities, supporting expansion into new markets, and ensuring extreme correctness and data integrity across user interfaces and core backend services.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design, develop, test, and optimize Angular applications using Typescript and modern development techniques.&lt;/li&gt;
&lt;li&gt;Build and evolve mission-critical tools and systems that allow Waymo to scale and serve new markets.&lt;/li&gt;
&lt;li&gt;Solve hard real-world problems related to event / incident response.&lt;/li&gt;
&lt;li&gt;Collaborate with Product, UX, and other engineers to design and develop internal user-facing products.&lt;/li&gt;
&lt;li&gt;Ship solutions to novel problems that arise in a fast-paced environment.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor&#39;s degree in Computer Science or equivalent practical experience.&lt;/li&gt;
&lt;li&gt;3+ years of experience in full-stack development.&lt;/li&gt;
&lt;li&gt;Strong understanding of web development fundamentals including HTML, CSS, and modern JavaScript/TypeScript.&lt;/li&gt;
&lt;li&gt;Knowledge of common frontend web development frameworks (e.g., Angular, React, Vue).&lt;/li&gt;
&lt;li&gt;Interest in backend development.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We prefer:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience developing Angular applications.&lt;/li&gt;
&lt;li&gt;Backend experience in Java, Python, Go, C++ or similar.&lt;/li&gt;
&lt;li&gt;Familiarity with Google infrastructure (e.g. Borg, Protocol Buffers, Spanner).&lt;/li&gt;
&lt;li&gt;Experience with engineering artifacts, reliability monitoring and alerting, documentation, integration testing, production hygiene, and support processes.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;

a16z-zipline:greenhouse:7753358003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Zipline&lt;/h3&gt;
&lt;p&gt;Zipline is the world’s largest and most experienced drone delivery service. We are on a mission to serve all humans equally by ensuring access to food, medicine and essential goods anytime, anywhere. We design, build, and operate the world’s largest autonomous logistics system, delivering critical supplies quickly and reliably. Today, Zipline operates on four continents, makes a delivery somewhere in the world every 30 seconds, and has completed millions of deliveries to date, including blood, vaccines, medical supplies, food, and retail products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our customers include the world’s largest and most prominent healthcare systems, governments, retailers, restaurants and global businesses who rely on us to save lives, reduce emissions, increase economic opportunity, and provide delivery from point A to point B as fast as possible. The drone is only 15% of what we’ve built to enable seamless, reliable, global operations.&lt;/p&gt;
&lt;p&gt;Our system strengthens supply chains, reduces congestion, and gives people time back. With more than 140 million commercial autonomous miles safely flown, Zipline is redefining access to healthcare, consumer products, and food across the globe.&lt;/p&gt;
&lt;p&gt;We operate at a global scale and are looking for practical problem solvers who thrive on real-world challenges and rapid growth. Our team is motivated by building systems that have a direct, meaningful impact on people’s lives and by scaling the future of logistics. We are seeking people who sculpt from first principles, enjoy facing adversity, and can do the impossible at record breaking speeds.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;
&lt;h3 class=&quot;content&quot;&gt;&lt;strong&gt;About You and The Role&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;As a Service Engineer I on Zipline’s Service Operations team, you will provide first-level technical support for grounded aircraft, droids, docks, and related operational systems. Your primary responsibility is to help return assets to service quickly, safely, and consistently by following approved troubleshooting guides, diagnostic workflows, and escalation procedures.&lt;/p&gt;
&lt;p&gt;This role is designed for technically curious operators who are calm under pressure, disciplined in following procedures, and strong at communicating across teams. This role is not expected to independently resolve highly complex or novel technical issues without support. Instead, success as a Service Engineer I comes from executing documented troubleshooting steps, capturing clear information, coordinating with the right teams, and escalating issues when additional Service Engineer II, Engineering, Maintenance, or Support Operations support is required.&lt;/p&gt;
&lt;p&gt;You will work closely with Service Engineer II teammates, Software Engineering, Hardware Engineering, Technical Writing, Maintenance, and Support Operations teams to improve troubleshooting documentation, identify process gaps, and help get aircraft and other operational assets back to airworthiness.&lt;/p&gt;
&lt;p&gt;This is a 24/7 operational support role that directly contributes to Zipline’s ability to serve customers around the world.&lt;/p&gt;
&lt;h3 class=&quot;content&quot;&gt;What You&#39;ll Do&amp;nbsp;&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;As a Service Engineer I, you will support grounded aircraft, droids, docks, and related operational systems by following approved troubleshooting guides and diagnostic procedures.&lt;/p&gt;
&lt;p&gt;You will:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Support asset recovery and airworthiness:&lt;/strong&gt; Use approved troubleshooting guides, checklists, diagnostic tools, and escalation paths to help return grounded assets to service safely and efficiently.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Execute first-level troubleshooting&lt;/strong&gt;: Work through step-by-step troubleshooting workflows created by Software Engineering, Hardware Engineering, Maintenance, and Technical Writing teams. Ensure required steps are completed and documented before escalating issues.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Triage incoming issues&lt;/strong&gt;: Review tickets, alerts, logs, and operational reports to understand the issue, determine severity, and prioritize work based on safety, customer impact, and operational need.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Escalate clearly and effectively&lt;/strong&gt;: Identify when an issue requires support from Service Engineer II, Engineering, Maintenance, or Support Operations. Provide clear context, completed troubleshooting steps, relevant logs, and recommended next actions during escalation.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Coordinate with maintenance teams&lt;/strong&gt;: Create work orders and support smooth handoffs when physical inspection, repair, replacement, or maintenance activity is required.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Document troubleshooting activity:&lt;/strong&gt; Accurately record actions taken, outcomes, unresolved symptoms, and lessons learned in the appropriate systems. Ensure documentation supports operational traceability, shift handoffs, and regulatory requirements.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Improve troubleshooting guides&lt;/strong&gt;: Provide feedback to Technical Writing, Engineering, and Maintenance teams when guides are unclear, outdated, incomplete, or difficult to execute in real operational conditions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Support 24/7 operations: &lt;/strong&gt;Participate in shift-based operations, including nights, weekends, holidays, handovers, and incident response workflows as needed to maintain continuous coverage.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Use Zipline operational tools&lt;/strong&gt;: Work in systems such as Zerp, Fleet Apps, incident.io, ticketing tools, diagnostic dashboards, and other internal platforms used to monitor, troubleshoot, and return assets to service.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Contribute to continuous improvement&lt;/strong&gt;: Identify recurring issues, documentation gaps, tooling friction, and opportunities to make first-level troubleshooting faster, clearer, and more repeatable.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;section-wrapper page-full-width&quot;&gt;What You&#39;ll Bring&amp;nbsp;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Strong execution and follow-through&lt;/strong&gt;: You are comfortable working from procedures, checklists, and troubleshooting guides, and you can reliably complete documented steps in high-pressure operational environments.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Technical curiosity&lt;/strong&gt;: You are interested in learning how complex systems work, including aircraft, robotics, hardware, software, docks, and fleet operations. You do not need to be an expert in all of these areas, but you should be eager to learn.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Operational discipline&lt;/strong&gt;: You understand the importance of safety, quality, compliance, and documentation when working in a regulated or high-stakes environment.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Clear communication&lt;/strong&gt;: You can explain what happened, what you tried, what changed, and what help is needed. You are comfortable coordinating with Service Engineer II teammates, Engineering, Maintenance, Technical Writing, and Operations teams.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Basic troubleshooting ability&lt;/strong&gt;: You have experience investigating technical or operational issues using guides, logs, dashboards, tools, or documented workflows.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Comfort with ambiguity:&lt;/strong&gt; You can stay calm when an issue is unclear, follow the available process, ask good questions, and escalate appropriately.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Documentation mindset&lt;/strong&gt;: You understand that accurate notes, ticket updates, and handoff details are essential for operational continuity, safety, compliance, and continuous improvement.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Team-first approach:&lt;/strong&gt; You work well across shifts, functions, and time zones. You understand that strong handoffs and shared context are critical in a 24/7 operation.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;2+ years of related experience required, and/or a bachelor’s degree or higher preferred. Experience in one or more of the following areas is helpful, but not required:&lt;/li&gt;
&lt;li&gt;Technical support, service operations, maintenance coordination, aviation operations, robotics operations, hardware support, fleet operations, manufacturing support, field operations, or customer operations.&lt;/li&gt;
&lt;li&gt;Experience working with ticketing systems, incident management tools, ERP systems, fleet management tools, or operational dashboards.&lt;/li&gt;
&lt;li&gt;Experience following technical documentation, standard operating procedures, maintenance instructions, or troubleshooting guides.&lt;/li&gt;
&lt;li&gt;Exposure to aircraft, drones, robotics, electromechanical systems, logistics systems, or complex operational environments.&lt;/li&gt;
&lt;li&gt;Experience working in a 24/7 shift-based operations environment.&lt;/li&gt;
&lt;li&gt;Experience providing feedback to improve technical documentation, training materials, standard operating procedures, or troubleshooting guides.&lt;/li&gt;
&lt;li&gt;Intermediate familiarity with logs, telemetry, dashboards, or diagnostic tools.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;content-wrapper posting-page&quot;&gt;What Else You Need to Know&amp;nbsp; &amp;nbsp;&lt;/h3&gt;
&lt;p&gt;This role requires working in&lt;strong&gt; 24/7 shift operations, including nights, weekends, and &lt;/strong&gt;holidays, as part of our continuous coverage model. You may participate in on-call rotations and must be available for rapid response when critical assets are grounded.&lt;/p&gt;
&lt;p&gt;This position operates in a fast-paced, safety-focused, and highly operational environment. Your work directly supports customer deliveries, asset availability, and Zipline’s ability to operate reliably at global scale.&lt;/p&gt;
&lt;p&gt;This role may require sitting or standing for extended periods while reviewing tickets, monitoring dashboards, conducting troubleshooting, documenting activity, and coordinating with cross-functional teams.&lt;/p&gt;
&lt;p&gt;Occasional travel may be required for training, certification, or site support activities, approximately 10%.&lt;/p&gt;
&lt;p&gt;You must be eligible to work in Rwanda.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;Zipline is an equal opportunity employer and prohibits discrimination and harassment of any type without regard to&amp;nbsp;race, color, ancestry, national origin, religion or religious creed, mental or physical disability, medical condition, genetic information, sex (including pregnancy, childbirth, and related medical conditions), sexual orientation, gender identity, gender expression, age, marital status, military or veteran status, citizenship, or other characteristics protected by state, federal or local law or our other policies.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We value diversity at Zipline and welcome applications from those who are traditionally underrepresented in tech. If you like the sound of this position but are not sure if you are the perfect fit, please apply!&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

adventinternational-ebanx:greenhouse:770.descriptionHtml:
&lt;p&gt;EBANX is one of the most successful fintechs to emerge from Latin America — and today, we are building a truly global payments company. Our mission has remained constant from day one: to unlock access and enable companies and consumers to participate in the digital economy, no matter where they are.&lt;br&gt;&lt;br&gt;What started as a bold vision has grown into a platform that connects some of the world’s largest digital businesses with customers across 21 of the fastest-growing markets. We operate where complexity exists — turning local challenges into global opportunities, and building the infrastructure that allows payments to move further, faster, and smarter.&lt;br&gt;&lt;br&gt;We are a team of builders and problem-solvers. We think globally, act with curiosity, and believe diversity of thought is a competitive advantage.&lt;/p&gt;
&lt;p&gt;As EBANX enters its next phase of hyper growth, we are looking for people who want to shape the future of payments, expand what’s possible, and help connect businesses and consumers across borders.&lt;br&gt;Let’s build what’s next — together.&lt;/p&gt;
&lt;p&gt;At EBANX’s Corporate areas, you don’t just keep operations running. You work behind the scenes to ensure every part of the company is connected, efficient, and ready to grow. Every project and process is driven by strategy, collaboration, and impact, making our work truly &lt;strong&gt;Out Of The Ordinary&lt;/strong&gt;.&lt;/p&gt;
